 import { gsap } from 'gsap';
import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, BoxGeometry, PlaneGeometry, TorusGeometry, Mesh, PointLight, Vector3, Color } = ctx.THREE;

  const group = new Group();
  group.name = config.id || 'home-stat-tile';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  const width = 1.6;
  const height = 1.0;
  const depth = 0.08;

  const cardGeo = new BoxGeometry(width, height, depth);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: surface,
    metalness: 0.55,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3
  });
  const card = new Mesh(cardGeo, cardMat);
  card.name = 'machined-card';
  card.castShadow = true;
  card.receiveShadow = true;
  group.add(card);

  const edgeGeo = new TorusGeometry(Math.max(width, height) * 0.55, 0.012, 8, 64);
  const edgeMat = new MeshPhysicalNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.2,
    metalness: 0.6,
    roughness: 0.4
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = depth / 2 + 0.01;
  group.add(edge);

  const gearHolder = new Group();
  gearHolder.name = 'stat-gear-holder';
  gearHolder.position.z = depth / 2 + 0.02;
  group.add(gearHolder);

  let gltfResources = [];

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene ? (gltf.scene.clone ? gltf.scene.clone() : gltf.scene) : new Group();
      scene.name = 'stat-gear';
      scene.scale.setScalar(0.28);
      scene.rotation.x = Math.PI / 2;
      gearHolder.add(scene);
      scene.traverse((o) => { if (o) gltfResources.push(o); });
    });
  }

  const shadowGeo = new PlaneGeometry(width * 1.3, height * 1.3);
  const shadowMat = new MeshBasicNodeMaterial({ color: 0x000000, transparent: true, opacity: 0.45 });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.06;
  group.add(shadow);

  const fillLight = new PointLight(paper, 0.45, 6);
  fillLight.position.set(-0.6, 0.8, 1.2);
  group.add(fillLight);

  const rimLight = new PointLight(accent, 0.9, 5);
  rimLight.position.set(1.0, -0.6, 1.0);
  group.add(rimLight);

  const primitiveResults = [];
  for (const primitive of config.cinematicPrimitives ?? []) {
    if (ctx.primitives?.[primitive.name]) {
      const res = ctx.primitives[primitive.name](group, primitive.params ?? {});
      if (res) primitiveResults.push(res);
    }
  }

  const gearTL = gsap.to(gearHolder.rotation, {
    z: '+=6.28318',
    duration: 24,
    repeat: -1,
    ease: 'none'
  });

  group.userData.handlers = {
    pointerenter: () => {
      gsap.to(group.position, {
        y: group.position.y + 0.15,
        duration: 0.35,
        ease: 'power2.out',
        overwrite: true
      });
      gsap.to(edgeMat, { emissiveIntensity: 1.8, duration: 0.3 });
    },
    pointerleave: () => {
      gsap.to(group.position, {
        y: group.position.y - 0.15,
        duration: 0.35,
        ease: 'power2.out',
        overwrite: true
      });
      gsap.to(edgeMat, { emissiveIntensity: 1.2, duration: 0.3 });
    },
    pointerdown: () => {
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        overwrite: true
      });
    },
    pointerup: () => {
      gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.25,
        ease: 'power2.out',
        overwrite: true
      });
    },
    click: () => {
      ctx.emit('hub-home.select', { source: config.id || group.name });
    }
  };

  group.userData.cleanup = () => {
    gearTL.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMat);

    for (const res of primitiveResults) {
      if (res && typeof res.cleanup === 'function') res.cleanup();
    }

    cardGeo.dispose();
    cardMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    for (const o of gltfResources) {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) {
          o.material.forEach((m) => m.dispose());
        } else {
          o.material.dispose();
        }
      }
    }
    gltfResources = [];
  };

  return group;
}
